<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\Crypt;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Http;
use Illuminate\Support\Str;

class AiController extends Controller {
 private function setting(int $c,string $key):?string{$v=DB::table('settings')->where(['company_id'=>$c,'group'=>'ai','key'=>$key])->value('value');return $v;}
 private function provider(int$c):string{return$this->setting($c,'provider')?:((string)config('services.gemini.api_key')!==''?'gemini':'openai');}
 private function key(int$c,?string$provider=null):?string{$provider??=$this->provider($c);if($provider==='gemini')return config('services.gemini.api_key')?:null;$v=$this->setting($c,'api_key');if(!$v)return null;try{return Crypt::decryptString($v);}catch(\Throwable){return null;}}
 private function gemini(string$key,string$model,array$parts){return Http::timeout(120)->withHeaders(['x-goog-api-key'=>$key])->post("https://generativelanguage.googleapis.com/v1beta/models/{$model}:generateContent",['contents'=>[['role'=>'user','parts'=>$parts]],'generationConfig'=>['temperature'=>0.2]]);}
 private function log(Request $r,string $feature,string $model,$prompt,$response,string $status,int $tokens=0,float $cost=0):int{return DB::table('ai_logs')->insertGetId(['company_id'=>$r->user()->company_id,'user_id'=>$r->user()->id,'feature'=>$feature,'model'=>$model,'prompt'=>is_string($prompt)?$prompt:json_encode($prompt),'response'=>is_string($response)?$response:json_encode($response),'tokens'=>$tokens,'cost'=>$cost,'status'=>$status,'created_at'=>now(),'updated_at'=>now()]);}
 public function status(Request$r){$c=$r->user()->company_id;$provider=$this->provider($c);return response()->json(['success'=>true,'data'=>['configured'=>(bool)$this->key($c,$provider),'provider'=>$provider,'model'=>$this->setting($c,'model')?:($provider==='gemini'?config('services.gemini.model'):'gpt-5.6-sol'),'logs'=>DB::table('ai_logs')->where('company_id',$c)->latest()->limit(20)->get(),'usage'=>DB::table('ai_logs')->where('company_id',$c)->selectRaw('COUNT(*) requests,COALESCE(SUM(tokens),0) tokens,COALESCE(SUM(cost),0) cost')->first()]]);}
 public function configure(Request$r){$d=$r->validate(['provider'=>'required|in:gemini,openai','api_key'=>'nullable|string','model'=>'required|string']);$c=$r->user()->company_id;if(!empty($d['api_key'])&&$d['provider']==='openai')DB::table('settings')->updateOrInsert(['company_id'=>$c,'group'=>'ai','key'=>'api_key'],['value'=>Crypt::encryptString($d['api_key']),'created_at'=>now(),'updated_at'=>now()]);foreach(['provider','model']as$key)DB::table('settings')->updateOrInsert(['company_id'=>$c,'group'=>'ai','key'=>$key],['value'=>$d[$key],'created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Configuración de IA guardada']);}
 public function insights(Request $r){$c=$r->user()->company_id;$low=DB::table('products as p')->join('stocks as s','s.product_id','=','p.id')->where('p.company_id',$c)->whereColumn('s.quantity','<=','p.minimum_stock')->select('p.id','p.name','s.quantity','p.minimum_stock')->get();$top=DB::table('sale_details as d')->join('sales as s','s.id','=','d.sale_id')->where('s.company_id',$c)->where('s.created_at','>=',now()->subDays(30))->groupBy('d.product_id','d.product_name')->selectRaw('d.product_id,d.product_name,SUM(d.quantity) quantity,SUM(d.total-d.quantity*d.historical_unit_cost) profit')->orderByDesc('quantity')->limit(10)->get();$pricing=DB::table('products as p')->join('stocks as s','s.product_id','=','p.id')->where('p.company_id',$c)->select('p.id','p.name','p.average_cost','p.sale_price','s.quantity')->get()->map(function($p){$margin=$p->sale_price?($p->sale_price-$p->average_cost)/$p->sale_price*100:0;$recommended=round(max($p->average_cost*1.25,$p->sale_price),2);return['id'=>$p->id,'name'=>$p->name,'current_price'=>(float)$p->sale_price,'margin'=>round($margin,1),'recommended_price'=>$recommended,'reason'=>$margin<20?'Margen inferior al 20%':'Precio saludable'];});return response()->json(['success'=>true,'data'=>['low_stock'=>$low,'top_products'=>$top,'pricing'=>$pricing]]);}
 public function ask(Request$r){$d=$r->validate(['question'=>'required|string|max:4000']);$c=$r->user()->company_id;$provider=$this->provider($c);$key=$this->key($c,$provider);abort_unless($key,422,'Configura una clave para el proveedor de IA');$model=$this->setting($c,'model')?:($provider==='gemini'?config('services.gemini.model'):'gpt-5.6-sol');$context=['sales_today'=>DB::table('sales')->where('company_id',$c)->whereDate('created_at',today())->sum('total'),'sales_month'=>DB::table('sales')->where('company_id',$c)->where('created_at','>=',now()->startOfMonth())->sum('total'),'stock_value'=>(float)(DB::table('products as p')->join('stocks as s','s.product_id','=','p.id')->where('p.company_id',$c)->selectRaw('SUM(s.quantity*p.average_cost) total')->value('total')??0),'critical_stock'=>DB::table('products as p')->join('stocks as s','s.product_id','=','p.id')->where('p.company_id',$c)->where('p.status','active')->whereColumn('s.quantity','<=','p.minimum_stock')->distinct()->count('p.id')];$instruction='Eres un analista de retail para una empresa peruana. Responde en español, usa únicamente los datos proporcionados y señala cualquier dato faltante.';$prompt=$instruction."\nContexto ERP: ".json_encode($context,JSON_UNESCAPED_UNICODE)."\nPregunta: ".$d['question'];if($provider==='gemini'){$response=$this->gemini($key,$model,[['text'=>$prompt]]);$json=$response->json();$text=collect($json['candidates'][0]['content']['parts']??[])->pluck('text')->implode("\n");$tokens=(int)($json['usageMetadata']['totalTokenCount']??0);}else{$response=Http::timeout(90)->withToken($key)->post('https://api.openai.com/v1/responses',['model'=>$model,'instructions'=>$instruction,'input'=>"Contexto ERP: ".json_encode($context,JSON_UNESCAPED_UNICODE)."\nPregunta: ".$d['question']]);$json=$response->json();$text=collect($json['output']??[])->flatMap(fn($o)=>$o['content']??[])->where('type','output_text')->pluck('text')->implode("\n");$tokens=(int)($json['usage']['total_tokens']??0);}if(!$response->successful()||$text===''){$this->log($r,'assistant',$model,$d['question'],$response->body(),'failed');abort($response->status()>=400?$response->status():422,'El proveedor de IA rechazó la solicitud: '.($response->json('error.message')?:'respuesta vacía'));}$this->log($r,'assistant',$model,$d['question'],$text,'completed',$tokens);return response()->json(['success'=>true,'data'=>['answer'=>$text,'provider'=>$provider,'model'=>$model,'tokens'=>$tokens]]);}
 public function ocr(Request $r){
  $r->validate(['image'=>'required|image|max:10240']);
  $c=$r->user()->company_id;$provider=$this->provider($c);$key=$this->key($c,$provider);
  abort_unless($key,422,'Configura una clave para usar OCR');
  $model=$this->setting($c,'model')?:($provider==='gemini'?config('services.gemini.model'):'gpt-5.6-sol');$file=$r->file('image');
  $base64=base64_encode(file_get_contents($file->getRealPath()));$data='data:'.$file->getMimeType().';base64,'.$base64;
  if($provider==='gemini'){$prompt='Extrae esta factura o boleta de compra. Devuelve únicamente JSON válido con proveedor, ruc, fecha, numero, moneda, subtotal, igv, total e items (descripcion,cantidad,costo_unitario,total). No inventes datos ilegibles.';$response=$this->gemini($key,$model,[['text'=>$prompt],['inline_data'=>['mime_type'=>$file->getMimeType(),'data'=>$base64]]]);if(!$response->successful()){$this->log($r,'ocr',$model,$file->getClientOriginalName(),$response->body(),'failed');abort($response->status(),'No se pudo procesar el documento con Gemini');}$json=$response->json();$text=collect($json['candidates'][0]['content']['parts']??[])->pluck('text')->implode("\n");$tokens=(int)($json['usageMetadata']['totalTokenCount']??0);$id=$this->log($r,'ocr',$model,$file->getClientOriginalName(),$text,'completed',$tokens);return response()->json(['success'=>true,'data'=>['id'=>$id,'result'=>$text,'tokens'=>$tokens]]);}
  $payload=[
   'model'=>$model,
   'input'=>[[
    'role'=>'user',
    'content'=>[
     ['type'=>'input_text','text'=>'Extrae esta factura o boleta de compra. Devuelve JSON válido con proveedor, ruc, fecha, numero, moneda, subtotal, igv, total e items (descripcion,cantidad,costo_unitario,total). No inventes datos ilegibles.'],
     ['type'=>'input_image','image_url'=>$data],
    ],
   ]],
  ];
  $response=Http::timeout(120)->withToken($key)->post('https://api.openai.com/v1/responses',$payload);
  if(!$response->successful()){$this->log($r,'ocr',$model,$file->getClientOriginalName(),$response->body(),'failed');abort($response->status(),'No se pudo procesar el documento');}
  $json=$response->json();$text=collect($json['output']??[])->flatMap(fn($o)=>$o['content']??[])->where('type','output_text')->pluck('text')->implode("\n");$tokens=(int)($json['usage']['total_tokens']??0);
  $id=$this->log($r,'ocr',$model,$file->getClientOriginalName(),$text,'completed',$tokens);
  return response()->json(['success'=>true,'data'=>['id'=>$id,'result'=>$text,'tokens'=>$tokens]]);
 }
 public function correctOcr(Request$r,int$id){$d=$r->validate(['result'=>'required|string|max:50000']);$q=DB::table('ai_logs')->where(['id'=>$id,'company_id'=>$r->user()->company_id,'feature'=>'ocr']);$q->firstOrFail();$q->update(['response'=>$d['result'],'status'=>'corrected','updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Corrección OCR guardada']);}
 public function ocrPurchase(Request$r,int$id){$c=$r->user()->company_id;$b=$r->user()->branch_id;$u=$r->user()->id;$log=DB::table('ai_logs')->where(['id'=>$id,'company_id'=>$c,'feature'=>'ocr'])->firstOrFail();$raw=trim(preg_replace('/^```(?:json)?|```$/m','',(string)$log->response));$data=json_decode($raw,true);abort_unless(is_array($data)&&!empty($data['items']),422,'El resultado corregido debe ser JSON válido con items');return DB::transaction(function()use($data,$c,$b,$u,$id){$supplier=!empty($data['ruc'])?DB::table('suppliers')->where(['company_id'=>$c,'document_number'=>$data['ruc']])->first():null;$items=[];$unmatched=[];foreach($data['items']as$item){$description=trim((string)($item['descripcion']??''));$p=DB::table('products')->where('company_id',$c)->where(fn($q)=>$q->where('name',$description)->orWhere('sku',$description)->orWhere('barcode',$description))->first();if(!$p){$unmatched[]=$description;continue;}$items[]=['product'=>$p,'quantity'=>(float)($item['cantidad']??1),'cost'=>(float)($item['costo_unitario']??0)];}abort_if($unmatched,422,'No se encontraron estos productos: '.implode(', ',$unmatched));$subtotal=collect($items)->sum(fn($x)=>$x['quantity']*$x['cost']);$number='OCR-'.str_pad((string)(DB::table('purchases')->where('company_id',$c)->count()+1),6,'0',STR_PAD_LEFT);$pid=DB::table('purchases')->insertGetId(['uuid'=>Str::uuid(),'company_id'=>$c,'branch_id'=>$b,'supplier_id'=>$supplier?->id,'user_id'=>$u,'number'=>$number,'invoice_number'=>$data['numero']??null,'document_type'=>'invoice','subtotal'=>$subtotal,'tax'=>(float)($data['igv']??0),'freight'=>0,'perception'=>0,'other_costs'=>0,'total'=>(float)($data['total']??($subtotal+(float)($data['igv']??0))),'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);foreach($items as$x)DB::table('purchase_details')->insert(['purchase_id'=>$pid,'product_id'=>$x['product']->id,'quantity'=>$x['quantity'],'unit_cost'=>$x['cost'],'effective_unit_cost'=>$x['cost'],'total'=>$x['quantity']*$x['cost'],'created_at'=>now(),'updated_at'=>now()]);DB::table('ai_logs')->where('id',$id)->update(['status'=>'imported','updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Compra OCR creada como pendiente para revisión','data'=>['id'=>$pid,'number'=>$number]],201);});}
}
